package org.sleepwell.app;
import android.content.Context;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.io.*;import java.security.MessageDigest;import java.util.*;import java.util.function.BooleanSupplier;import java.util.zip.*;
/** Read-only whole-library snapshot. All-or-error: no clipped audio or silently omitted rows. */
final class LibraryAudioArchive {
 static final int MAX_CLIPS=999,MAX_EVENTS=20000,MAX_RECORDS=2000;static final long MAX_BYTES=256L*1024*1024;
 static final class Audio {final JSONObject row;final long bytes,duration;final String sha256,name;Audio(JSONObject row,long bytes,long duration,String hash,int index){this.row=row;this.bytes=bytes;this.duration=duration;sha256=hash;name=String.format(Locale.ROOT,"recordings/%06d.wav",index+1);}}
 static final class Metadata {final List<JSONObject> clips,events,records;final String fingerprint,document;Metadata(List<JSONObject> clips,List<JSONObject> events,List<JSONObject> records,String fingerprint,String document){this.clips=List.copyOf(clips);this.events=List.copyOf(events);this.records=List.copyOf(records);this.fingerprint=fingerprint;this.document=document;}}
 static final class Plan {final Metadata metadata;final List<Audio> audio;final long bytes;Plan(Metadata metadata,List<Audio> audio,long bytes){this.metadata=metadata;this.audio=List.copyOf(audio);this.bytes=bytes;}}
 private static void active(BooleanSupplier running)throws InterruptedIOException{NightAudioArchive.active(running);}
 private static Metadata metadata(Store store,BooleanSupplier running)throws Exception{
  active(running);if(TrackingService.running)throw new IOException("End tracking before exporting the complete library.");SQLiteDatabase db=store.getReadableDatabase();db.beginTransactionNonExclusive();try{
   List<JSONObject> clips=store.rows("SELECT * FROM clips ORDER BY session,time,id LIMIT "+(MAX_CLIPS+1)),events=store.rows("SELECT * FROM sound_events ORDER BY session,time,id LIMIT "+(MAX_EVENTS+1));if(clips.size()>MAX_CLIPS||events.size()>MAX_EVENTS)throw large();
   List<JSONObject> raw=store.rows("SELECT s.* FROM sessions s WHERE EXISTS(SELECT 1 FROM clips c WHERE c.session=s.id) OR EXISTS(SELECT 1 FROM sound_events e WHERE e.session=s.id) ORDER BY s.id LIMIT "+(MAX_RECORDS+1));if(raw.size()>MAX_RECORDS)throw large();List<JSONObject> records=new ArrayList<>();Set<Long> known=new HashSet<>();
   for(JSONObject row:raw){active(running);long id=row.optLong("id");if(id<=0||row.isNull("end"))throw new IOException("An unfinished recording still has audio. Recover or finish it before exporting.");known.add(id);JSONObject value=new JSONObject();for(String key:List.of("id","start","end","source","origin","zone","sensor","sensor_config","sound_analysis","interrupted","clock_changed"))value.put(key,row.opt(key));List<JSONObject> edits=store.rows("SELECT start,end,updated,reverted FROM record_edits WHERE session=?",""+id);JSONObject edit=edits.isEmpty()?null:edits.get(0);boolean edited=edit!=null&&edit.optInt("reverted")==0;value.put("visible_start",edited?edit.optLong("start"):row.optLong("start")).put("visible_end",edited?edit.optLong("end"):row.optLong("end")).put("edited",edited).put("edit_revision",edit==null?0:edit.optLong("updated"));records.add(value);}
   for(JSONObject clip:clips){if(!known.contains(clip.optLong("session")))throw new IOException("A recording has no source night.");if(SoundClips.pending(store,clip.optLong("id")))throw new IOException("Finish pending audio deletions before exporting.");}
   for(JSONObject event:events)if(!known.contains(event.optLong("session")))throw new IOException("A sound event has no source night.");
   long metadataBytes=0;for(List<JSONObject> group:List.of(records,clips,events))for(JSONObject row:group){active(running);metadataBytes+=row.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(metadataBytes>8L*1024*1024)throw new IOException("Library metadata exceeds 8 MB. Export individual nights instead; nothing was omitted.");}
   String document=store.backup().toString(2);BackupIo.encode(document);
   String fingerprint=NightAudioArchive.hash(MessageDigest.getInstance("SHA-256").digest(new JSONObject().put("backup",document).put("records",new JSONArray(records)).put("clips",new JSONArray(clips)).put("events",new JSONArray(events)).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));db.setTransactionSuccessful();return new Metadata(clips,events,records,fingerprint,document);
  }finally{db.endTransaction();}
 }
 private static IOException large(){return new IOException("The library exceeds this export's 999 recordings, 20,000 events, 2,000 nights or 256 MB limit. Export individual nights instead; nothing was omitted.");}
 private static File checked(Context context,JSONObject row)throws IOException{return FileSafety.clip(context,row.optString("path"));}
 private static String copy(RandomAccessFile source,OutputStream output,long expected,BooleanSupplier running)throws Exception{source.seek(0);MessageDigest digest=MessageDigest.getInstance("SHA-256");byte[] buffer=new byte[65536];long total=0;for(int count;(count=source.read(buffer))!=-1;){active(running);total+=count;if(total>expected)throw new IOException("A recording changed. Refresh the export review.");digest.update(buffer,0,count);if(output!=null)output.write(buffer,0,count);}if(total!=expected||source.length()!=expected)throw new IOException("A recording changed. Refresh the export review.");return NightAudioArchive.hash(digest.digest());}
 static Plan prepare(Context app,Store store,BooleanSupplier running)throws Exception{synchronized(SoundClips.LOCK){Metadata baseline=metadata(store,running);List<Audio> audio=new ArrayList<>();long total=0;for(JSONObject row:baseline.clips){active(running);try(RandomAccessFile in=new RandomAccessFile(checked(app,row),"r")){long bytes=in.length();if(bytes<44||bytes>16L*1024*1024)throw new IOException("A saved recording is missing or unsupported.");total=Math.addExact(total,bytes);if(total>MAX_BYTES)throw large();ClipWave wave=ClipWave.read(in,0,Long.MAX_VALUE);audio.add(new Audio(row,bytes,wave.durationMs,copy(in,null,bytes,running),audio.size()));}}same(store,baseline,running);return new Plan(baseline,audio,total);}}
 private static void same(Store store,Metadata expected,BooleanSupplier running)throws Exception{if(!metadata(store,running).fingerprint.equals(expected.fingerprint))throw new IOException("The sound library changed. Refresh the export review before choosing a new destination.");}
 static final class Snapshot implements AutoCloseable {final AudioArchiveWorkspace workspace;final Plan plan;final byte[] manifest;Snapshot(AudioArchiveWorkspace workspace,Plan plan,byte[] manifest){this.workspace=workspace;this.plan=plan;this.manifest=manifest;}
  void write(OutputStream destination,BooleanSupplier running)throws Exception{active(running);try(ZipOutputStream zip=new ZipOutputStream(destination,java.nio.charset.StandardCharsets.UTF_8)){zip.setLevel(Deflater.BEST_SPEED);for(int n=0;n<plan.audio.size();n++){active(running);Audio audio=plan.audio.get(n);ZipEntry entry=new ZipEntry(audio.name);entry.setTime(0);zip.putNextEntry(entry);try(RandomAccessFile source=new RandomAccessFile(workspace.file(n),"r")){if(!copy(source,zip,audio.bytes,running).equals(audio.sha256))throw new IOException("The private export snapshot changed.");}zip.closeEntry();}active(running);ZipEntry payload=new ZipEntry("backup.json");payload.setTime(0);zip.putNextEntry(payload);BackupIo.write(zip,BackupIo.encode(plan.metadata.document),running);zip.closeEntry();active(running);ZipEntry metadata=new ZipEntry("manifest.json");metadata.setTime(0);zip.putNextEntry(metadata);zip.write(manifest);zip.closeEntry();zip.finish();}}
  public void close()throws IOException{workspace.close();}
 }
 static Snapshot stage(Context app,Store store,Plan plan,BooleanSupplier running)throws Exception{if(plan.audio.isEmpty())throw new IOException("There are no saved recordings to export.");AudioArchiveWorkspace workspace=AudioArchiveWorkspace.create(app,MAX_CLIPS);try{
  synchronized(SoundClips.LOCK){same(store,plan.metadata,running);for(int n=0;n<plan.audio.size();n++){active(running);Audio audio=plan.audio.get(n);try(RandomAccessFile source=new RandomAccessFile(checked(app,audio.row),"r");OutputStream destination=new FileOutputStream(workspace.file(n))){if(!copy(source,destination,audio.bytes,running).equals(audio.sha256))throw new IOException("A recording changed. Refresh the export review.");}}same(store,plan.metadata,running);}
  JSONArray clips=new JSONArray(),events=new JSONArray();Map<Long,String> names=new HashMap<>();for(Audio audio:plan.audio){active(running);names.put(audio.row.optLong("id"),audio.name);JSONObject row=new JSONObject().put("file",audio.name).put("original_clip_id",audio.row.optLong("id")).put("session",audio.row.optLong("session")).put("end_time",audio.row.optLong("time")).put("duration_ms",audio.duration).put("favorite",audio.row.optInt("favorite")==1).put("bytes",audio.bytes).put("sha256",audio.sha256).put("category",audio.row.optString("category","noise")).put("score",audio.row.optDouble("score",0)).put("level",audio.row.isNull("level")?JSONObject.NULL:audio.row.get("level"));clips.put(row);}
  for(JSONObject raw:plan.metadata.events){active(running);JSONObject row=new JSONObject();for(String key:List.of("id","session","time","duration_ms","category","score","model","favorite","user_category","label_revision"))row.put(key,raw.has(key)?raw.get(key):JSONObject.NULL);row.put("effective_category",SoundLabels.category(raw)).put("label_source",SoundLabels.manual(raw)?"user":"model");String name=names.get(raw.optLong("clip"));row.put("recording",name==null?JSONObject.NULL:name);events.put(row);}
  JSONObject manifest=new JSONObject().put("format","sleepwell-library-audio-archive").put("version",2).put("export_only",false).put("metadata_file","backup.json").put("metadata_sha256",NightAudioArchive.hash(MessageDigest.getInstance("SHA-256").digest(BackupIo.encode(plan.metadata.document)))).put("scope","all_saved_sound_library_complete_raw_clips").put("note","Complete WAV recordings can include audio outside edited sleep times. Model scores are uncalibrated estimates; user corrections remain explicit. The included backup.json preserves saved record and alarm metadata. Imported alarms stay off.").put("records",new JSONArray(plan.metadata.records)).put("recordings",clips).put("sound_events",events);byte[] bytes=manifest.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8);if(bytes.length>8*1024*1024)throw new IOException("Library metadata exceeds 8 MB. Export individual nights instead; nothing was omitted.");active(running);return new Snapshot(workspace,plan,bytes);
 }catch(Exception failure){try{workspace.close();}catch(IOException cleanup){failure.addSuppressed(cleanup);}throw failure;}}
}
